}
*,*::before,*::after{box-sizing:border-box}
body{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--f-disp);font-weight:700;letter-spacing:-.02em;line-height:1.08;text-wrap:balance;margin:0}
p{margin:0}
a{color:inherit}
button,input,select{font:inherit;color:inherit}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:2px}
.wrap{max-width:1240px;margin:0 auto;padding-inline:var(--pad)}
.eyebrow{font-family:var(--f-mono);font-size:11.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted);display:flex;align-items:center;gap:10px}
.eyebrow::before{content:"";width:22px;height:1px;background:var(--accent);flex:none}
.num{font-family:var(--f-mono);font-variant-numeric:tabular-nums}
.lede{font-size:clamp(17px,1.5vw,19.5px);color:var(--ink-2);max-width:62ch}

/* ---------- header ---------- */
.top{position:sticky;top:0;z-index:60;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(14px);border-bottom:1px solid var(--rule)}
.top-in{display:flex;align-items:center;gap:26px;height:66px}
.brand{display:flex;align-items:center;gap:11px;font-family:var(--f-disp);font-weight:700;font-size:19px;letter-spacing:-.03em;text-decoration:none;flex:none}
.mark{width:30px;height:30px;border-radius:7px;background:var(--accent);display:grid;place-items:center;flex:none}
.mark svg{width:16px;height:16px;display:block}
.brand small{font-family:var(--f-mono);font-weight:400;font-size:9.5px;letter-spacing:.18em;color:var(--muted);display:block;text-transform:uppercase;margin-top:-3px}
.nav{display:flex;gap:22px;margin-left:auto;font-size:14.5px}
.nav a{text-decoration:none;color:var(--ink-2);padding:6px 0;border-bottom:1.5px solid transparent}
.nav a:hover{color:var(--ink);border-bottom-color:var(--accent)}
.top-cta{display:flex;align-items:center;gap:14px;flex:none}
.tel{font-family:var(--f-mono);font-size:13.5px;text-decoration:none;color:var(--ink-2);white-space:nowrap}
.tel:hover{color:var(--accent-ink)}
.btn{display:inline-flex;align-items:center;gap:9px;border:1px solid transparent;border-radius:3px;padding:11px 20px;font-family:var(--f-disp);font-weight:600;font-size:14.5px;letter-spacing:-.01em;text-decoration:none;cursor:pointer;transition:transform .12s ease,background .15s ease,border-color .15s ease}
.btn-pri{background:var(--accent);color:#fff}
.btn-pri:hover{background:var(--accent-ink);transform:translateY(-1px)}
.btn-gho{background:transparent;color:var(--ink);border-color:var(--rule-2)}
.btn-gho:hover{border-color:var(--ink);transform:translateY(-1px)}
.btn-lt{background:#fff;color:var(--navy)}
.btn-lt:hover{transform:translateY(-1px)}
.themer{background:none;border:1px solid var(--rule);border-radius:3px;width:34px;height:34px;display:grid;place-items:center;cursor:pointer;color:var(--ink-2)}
.themer:hover{border-color:var(--rule-2);color:var(--ink)}
@media(max-width:1080px){.nav,.tel{display:none}}

/* ---------- hero ---------- */
.hero{border-bottom:1px solid var(--rule);background:var(--surface);overflow:hidden}
.hero-in{display:grid;grid-template-columns:1.06fr .94fr;gap:clamp(28px,4vw,60px);padding-block:clamp(44px,6vw,78px) 0;align-items:start}
h1{font-size:clamp(36px,5.1vw,64px);letter-spacing:-.035em}
h1 em{font-style:normal;color:var(--accent-ink);position:relative;white-space:nowrap}
h1 em::after{content:"";position:absolute;left:0;right:0;bottom:.06em;height:.1em;background:var(--accent);opacity:.28}
.hero-copy{display:flex;flex-direction:column;gap:24px;padding-bottom:clamp(44px,6vw,72px)}
.hero-acts{display:flex;flex-wrap:wrap;gap:12px;align-items:center}
.hero-note{font-family:var(--f-mono);font-size:12px;color:var(--muted);letter-spacing:.02em}
.sig{border:1px solid var(--rule);border-radius:4px;background:var(--surface-2);overflow:hidden;margin-bottom:clamp(44px,6vw,72px)}
.sig-h{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;border-bottom:1px solid var(--rule);font-family:var(--f-mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.dot{width:7px;height:7px;border-radius:50%;background:var(--accent);display:inline-block;margin-right:7px;vertical-align:middle}
.sig-rows{display:grid}
.sig-row{display:grid;grid-template-columns:1fr auto;gap:16px;align-items:baseline;padding:17px 16px;border-bottom:1px solid var(--rule)}
.sig-row:last-child{border-bottom:0}
.sig-row b{font-family:var(--f-disp);font-size:clamp(26px,3vw,36px);font-weight:700;letter-spacing:-.04em;font-variant-numeric:tabular-nums;line-height:1}
.sig-row span{font-size:14px;color:var(--ink-2);line-height:1.35}
.sig-row i{font-style:normal;font-family:var(--f-mono);font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);display:block;margin-bottom:5px}
.sig-foot{padding:12px 16px;font-family:var(--f-mono);font-size:11px;color:var(--muted);background:var(--inset)}
@media(max-width:900px){.hero-in{grid-template-columns:1fr;padding-bottom:0}.sig{margin-bottom:clamp(36px,6vw,60px)}.hero-copy{padding-bottom:8px}}

/* ---------- logos ---------- */
.strip{border-bottom:1px solid var(--rule);background:var(--bg)}
.strip-in{display:flex;align-items:center;gap:clamp(18px,3vw,44px);flex-wrap:wrap;padding-block:18px}
.strip-in p{font-family:var(--f-mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.strip-in span{font-family:var(--f-disp);font-weight:600;font-size:16px;letter-spacing:-.01em;color:var(--ink-2);opacity:.8}

/* ---------- generic section ---------- */
.sec{border-bottom:1px solid var(--rule);padding-block:clamp(52px,7vw,96px)}
.sec-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(20px,4vw,56px);align-items:end;margin-bottom:clamp(28px,4vw,48px)}
.sec-head h2{font-size:clamp(27px,3.4vw,42px)}
.sec-head .eyebrow{margin-bottom:14px}
@media(max-width:860px){.sec-head{grid-template-columns:1fr}}
