# -*- coding: utf-8 -*-
import io,os,re,html,json,shutil

BASE="https://www.oekovolt.com"
OUT=r"D:/Salzburg/oekovolt-rechner-deploy"
PUB=os.path.join(OUT,"public","rechner")
if os.path.isdir(OUT): shutil.rmtree(OUT)
os.makedirs(PUB)

PAGES=[
 ("oekovolt.html","photovoltaik-gewerbe","Photovoltaik für Gewerbe und Industrie | Anlagenkonfigurator",
  "Anlagengröße, Jahresertrag, Eigenverbrauchsquote und Amortisation für Ihr Hallendach berechnen. Konfigurator mit offengelegten Annahmen für Österreich."),
 ("lp/p01.html","stromspeicher","Gewerbespeicher berechnen | Lastgang-Simulator",
  "Speichergröße, Eigenverbrauch und Spitzenlastkappung über einen Betriebstag simulieren. Mit Ladezustand, Zyklen und Amortisation."),
 ("lp/p02.html","waermepumpe","Wärmepumpe für Betriebe | Heizsystem-Vergleich",
  "Wärmepumpe gegen Öl, Gas, Pellets und Direktstrom auf Basis des Nutzwärmebedarfs vergleichen. Mit PV-Deckung und Amortisation."),
 ("lp/p03.html","wallbox-flotte","Ladeinfrastruktur für Firmenflotten | Flottenplaner",
  "Anschlussspitze, Ladepunkte und PV-Deckung für Ihren Fuhrpark berechnen. Mit und ohne dynamisches Lastmanagement."),
 ("lp/p04.html","agri-photovoltaik","Agri-Photovoltaik | Flächenkonfigurator",
  "Reihenabstand, Lichtangebot am Boden, Kulturertrag und Flächeneffizienz im Schnitt durch die Anlage."),
 ("lp/p05.html","smart-energy-home","Smart Energy Home | Energiefluss-Simulator",
  "PV, Speicher, Wärmepumpe und Wallbox zuschalten und den Energiefluss über 24 Stunden verfolgen. Mit Autarkiegrad."),
 ("lp/p06.html","mieterstrom","Mieterstrom und Gemeinschaftsanlage | Verteilungsrechner",
  "Ersparnis je Einheit, Eigennutzung im Objekt und Erlös der Betreiberin bei statischer und dynamischer Aufteilung."),
 ("lp/p07.html","dynamischer-stromtarif","Dynamischer Stromtarif | Spotpreis-Planer",
  "Verschiebbare Prozesse in die günstigen Stunden legen und den Vorteil gegenüber dem Fixtarif sofort sehen."),
 ("lp/p08.html","direktvermarktung","Direktvermarktung von PV-Strom | Erlösrechner",
  "Marktwertfaktor, Monatserlöse und Break-even-Marktpreis im Vergleich zum fixen Abnahmepreis."),
 ("lp/p09.html","finanzierung","Photovoltaik finanzieren | Kauf, Kredit oder Contracting",
  "Kapitalflussvergleich der drei Finanzierungswege über zwanzig Jahre, inklusive Wechselrichtertausch und Break-even."),
 ("lp/p10.html","repowering","Photovoltaik Repowering | Anlagen-Check",
  "Istertrag gegen Degradationskurve prüfen und das Repowering-Potenzial auf derselben Dachfläche berechnen."),
 ("lp/hub.html","","Photovoltaik-Rechner für Betriebe | ÖKOVOLT",
  "Elf Rechner für Photovoltaik, Speicher, Wärmepumpe, Ladeinfrastruktur, Förderung und Finanzierung. Alle Annahmen offengelegt."),
]

FAQ_RE=re.compile(r'<details class="qa"[^>]*>\s*<summary>(.*?)</summary>\s*<p>(.*?)</p>',re.S)
def txt(s):
    s=re.sub(r"<[^>]+>","",s)
    return html.unescape(s).strip()

TRACK = """
<script>
/* ---- ÖKOVOLT Lead-Anbindung & Tracking ---------------------------------- */
(function(){
"use strict";
window.dataLayer=window.dataLayer||[];
var SLUG="__SLUG__", started=false;

function push(ev,extra){
  var o={event:ev,rechner:SLUG};
  if(extra)for(var k in extra)o[k]=extra[k];
  window.dataLayer.push(o);
}
function firstTouch(){ if(started)return; started=true; push("rechner_start"); }
document.addEventListener("input",function(e){
  if(e.target&&e.target.type==="range")firstTouch();
},true);
document.addEventListener("click",function(e){
  var t=e.target&&e.target.closest?e.target.closest(".seg button,.sw"):null;
  if(t)firstTouch();
},true);

/* Zustand des Rechners einsammeln: Eingaben + berechnete Kennzahlen */
window.oekovoltRechnerState=function(){
  var st={eingaben:{},ergebnisse:{}},i;
  Array.prototype.forEach.call(document.querySelectorAll(".con-l input[type=range]"),function(el){
    var lab=document.querySelector('label[for="'+el.id+'"]');
    var val=document.getElementById("v-"+el.id);
    st.eingaben[(lab?lab.textContent:el.id).trim()]=(val?val.textContent:el.value).trim();
  });
  Array.prototype.forEach.call(document.querySelectorAll('.seg button[aria-pressed="true"],.sw[aria-pressed="true"]'),function(el){
    st.eingaben[el.textContent.trim()]="aktiv";
  });
  Array.prototype.forEach.call(document.querySelectorAll(".stat"),function(el){
    var k=el.querySelector("i"),v=el.querySelector("b");
    if(k&&v)st.ergebnisse[k.textContent.trim()]=v.textContent.trim();
  });
  return st;
};

/* Formular: alte Demo-Handler entfernen, echten Versand anhängen */
var old=document.getElementById("form");
if(old){
  var f=old.cloneNode(true);
  old.parentNode.replaceChild(f,old);
  f.addEventListener("submit",function(e){
    e.preventDefault();
    var g=function(id){var el=f.querySelector("#"+id);return el?el.value.trim():"";};
    var box=f.querySelector("#sent");
    var btn=f.querySelector('button[type="submit"]');
    var mail=g("f-mail");
    if(!mail||mail.indexOf("@")<1){
      if(box){box.className="sent on";box.innerHTML="<b>E-Mail fehlt</b>Bitte tragen Sie eine E-Mail-Adresse ein, damit wir die Auslegung zusenden können.";}
      return;
    }
    var payload={
      quelle:SLUG, pfad:location.pathname, zeit:new Date().toISOString(),
      thema:g("f-topic")||document.title,
      unternehmen:g("f-comp"), ansprechpartner:g("f-name"), email:mail,
      dachform:g("f-roof"), dachflaeche:g("f-area"), verbrauch:g("f-use"),
      rechner:window.oekovoltRechnerState()
    };
    if(btn){btn.disabled=true;btn.textContent="Wird gesendet";}
    fetch("/api/anfrage",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)})
      .then(function(r){ if(!r.ok)throw new Error(r.status); return r.json().catch(function(){return {};}); })
      .then(function(){
        push("lead_submit",{thema:payload.thema});
        if(box){box.className="sent on";box.innerHTML="<b>Anfrage eingegangen</b>Wir melden uns innerhalb eines Werktags. Ihre eingestellten Werte haben wir mitgeschickt.";}
        if(btn){btn.textContent="Gesendet";}
      })
      .catch(function(){
        if(box){box.className="sent on";box.innerHTML="<b>Senden nicht möglich</b>Bitte versuchen Sie es erneut oder schreiben Sie an <a href=\\"mailto:office@oekovolt.at\\">office@oekovolt.at</a>.";}
        if(btn){btn.disabled=false;btn.textContent="Auslegung anfordern";}
      });
  });
}
})();
</script>
"""

def head_block(slug,title,desc,faq):
    url=BASE+"/rechner"+(("/"+slug) if slug else "")
    og=BASE+"/og/rechner-"+(slug or "uebersicht")+".png"
    h=[]
    h.append('<meta name="description" content="%s">'%html.escape(desc,quote=True))
    h.append('<link rel="canonical" href="%s">'%url)
    h.append('<meta name="robots" content="index,follow,max-image-preview:large">')
    h.append('<meta property="og:type" content="website">')
    h.append('<meta property="og:site_name" content="ÖKOVOLT Solartechnik">')
    h.append('<meta property="og:locale" content="de_AT">')
    h.append('<meta property="og:title" content="%s">'%html.escape(title,quote=True))
    h.append('<meta property="og:description" content="%s">'%html.escape(desc,quote=True))
    h.append('<meta property="og:url" content="%s">'%url)
    h.append('<meta property="og:image" content="%s">'%og)
    h.append('<meta name="twitter:card" content="summary_large_image">')
    ld={"@context":"https://schema.org","@graph":[{
        "@type":"WebApplication","name":title.split("|")[-1].strip() or title,
        "url":url,"applicationCategory":"BusinessApplication",
        "operatingSystem":"Web","inLanguage":"de-AT",
        "offers":{"@type":"Offer","price":"0","priceCurrency":"EUR"},
        "provider":{"@type":"Organization","name":"Ökovolt Solartechnik GmbH","url":BASE,
          "telephone":"+43 6278 71030","email":"office@oekovolt.at",
          "address":{"@type":"PostalAddress","streetAddress":"Gewerbegebiet 10","postalCode":"5121",
                     "addressLocality":"Ostermiething","addressCountry":"AT"}}}]}
    if faq:
        ld["@graph"].append({"@type":"FAQPage","mainEntity":[
