import { NextResponse } from "next/server";

/**
 * Nimmt die Anfragen der Rechnerseiten entgegen.
 * Der Body enthaelt die Kontaktdaten und den kompletten Zustand des Rechners,
 * also die eingestellten Werte und die daraus berechneten Kennzahlen.
 *
 * Benoetigte Umgebungsvariablen:
 *   LEAD_MAIL_TO       Zieladresse, z. B. office@oekovolt.at
 *   LEAD_MAIL_FROM     Absenderadresse der verifizierten Domain
 *   RESEND_API_KEY     Schluessel des Mailversands (oder eigener SMTP-Versand)
 *   LEAD_WEBHOOK_URL   optional, z. B. HubSpot oder ein anderes CRM
 */

export const runtime = "nodejs";

type Lead = {
  quelle?: string;
  pfad?: string;
  zeit?: string;
  thema?: string;
  unternehmen?: string;
  ansprechpartner?: string;
  email?: string;
  dachform?: string;
  dachflaeche?: string;
  verbrauch?: string;
  rechner?: {
    eingaben?: Record<string, string>;
    ergebnisse?: Record<string, string>;
  };
  /* Honeypot: von Menschen nie ausgefuellt */
  website?: string;
};

/* Einfache Ratenbegrenzung je IP, haelt Bots aus dem Postfach. */
const hits = new Map<string, number[]>();
const WINDOW_MS = 10 * 60 * 1000;
const MAX_PER_WINDOW = 5;

function rateLimited(ip: string) {
  const now = Date.now();
  const list = (hits.get(ip) ?? []).filter((t) => now - t < WINDOW_MS);
  list.push(now);
  hits.set(ip, list);
  return list.length > MAX_PER_WINDOW;
}

function table(obj: Record<string, string> = {}) {
  const rows = Object.entries(obj)
    .map(
      ([k, v]) =>
        `<tr><td style="padding:4px 14px 4px 0;color:#555">${esc(k)}</td>` +
        `<td style="padding:4px 0;font-family:monospace"><strong>${esc(v)}</strong></td></tr>`
    )
    .join("");
  return rows ? `<table style="border-collapse:collapse">${rows}</table>` : "<p>keine Angaben</p>";
}

function esc(s: string) {
  return String(s).replace(/[<>&]/g, (c) => ({ "<": "&lt;", ">": "&gt;", "&": "&amp;" }[c] as string));
}

export async function POST(req: Request) {
  const ip = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unbekannt";
  if (rateLimited(ip)) {
    return NextResponse.json({ ok: false, error: "zu viele Anfragen" }, { status: 429 });
  }

  let lead: Lead;
  try {
    lead = (await req.json()) as Lead;
  } catch {
    return NextResponse.json({ ok: false, error: "ungueltiger Body" }, { status: 400 });
  }

  /* Honeypot still verwerfen, damit Bots keinen Fehler sehen. */
  if (lead.website) return NextResponse.json({ ok: true });

  if (!lead.email || !lead.email.includes("@")) {
    return NextResponse.json({ ok: false, error: "E-Mail fehlt" }, { status: 400 });
  }

  const betreff = `Neue Anfrage: ${lead.thema ?? lead.quelle ?? "Rechner"} — ${
    lead.unternehmen || lead.ansprechpartner || lead.email
  }`;

  const html = `
    <h2 style="font-family:system-ui">${esc(betreff)}</h2>
    <p style="font-family:system-ui">
      <strong>Unternehmen:</strong> ${esc(lead.unternehmen ?? "—")}<br>
      <strong>Ansprechpartner:</strong> ${esc(lead.ansprechpartner ?? "—")}<br>
      <strong>E-Mail:</strong> <a href="mailto:${esc(lead.email)}">${esc(lead.email)}</a><br>
      <strong>Seite:</strong> ${esc(lead.pfad ?? "—")}<br>
      <strong>Zeitpunkt:</strong> ${esc(lead.zeit ?? new Date().toISOString())}
    </p>
    <h3 style="font-family:system-ui">Eingestellte Werte</h3>
    ${table(lead.rechner?.eingaben)}
    <h3 style="font-family:system-ui">Berechnete Kennzahlen</h3>
    ${table(lead.rechner?.ergebnisse)}
  `;

  /* 1) Weiterleitung ins CRM, sofern konfiguriert */
  if (process.env.LEAD_WEBHOOK_URL) {
    try {
      await fetch(process.env.LEAD_WEBHOOK_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(lead),
      });
    } catch (e) {
      console.error("CRM-Weiterleitung fehlgeschlagen", e);
    }
  }

  /* 2) Benachrichtigung ins Postfach */
  if (process.env.RESEND_API_KEY && process.env.LEAD_MAIL_TO) {
    const r = await fetch("https://api.resend.com/emails", {
      method: "POST",
      headers: {
        Authorization: `Bearer ${process.env.RESEND_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        from: process.env.LEAD_MAIL_FROM ?? "website@oekovolt.at",
        to: [process.env.LEAD_MAIL_TO],
        reply_to: lead.email,
        subject: betreff,
        html,
      }),
    });
    if (!r.ok) {
      console.error("Mailversand fehlgeschlagen", await r.text());
      return NextResponse.json({ ok: false, error: "Versand fehlgeschlagen" }, { status: 502 });
    }
  } else {
    /* Ohne Konfiguration wenigstens protokollieren, damit nichts verloren geht. */
    console.warn("Lead ohne Mailversand:", JSON.stringify(lead));
  }

  return NextResponse.json({ ok: true });
}

