/**
 * Ergänzung für die bestehende next.config.js von oekovolt.com.
 *
 * Die Rechnerseiten liegen als fertige HTML-Dateien unter
 *   public/rechner/<slug>/index.html
 * Next.js liefert Dateien aus public/ unverändert aus, hängt aber kein
 * index.html an einen Ordnerpfad an. Die Rewrites unten schließen genau
 * diese Lücke, damit /rechner und /rechner/stromspeicher funktionieren.
 *
 * Einbau: die Einträge aus rewrites() und headers() in die vorhandene
 * Konfiguration übernehmen. Falls dort bereits rewrites() existiert,
 * die Arrays zusammenführen statt zu ersetzen.
 */

const RECHNER = [
  "photovoltaik-gewerbe",
  "stromspeicher",
  "waermepumpe",
  "wallbox-flotte",
  "agri-photovoltaik",
  "smart-energy-home",
  "mieterstrom",
  "dynamischer-stromtarif",
  "direktvermarktung",
  "finanzierung",
  "repowering",
];

/** @type {import('next').NextConfig} */
module.exports = {
  async rewrites() {
    return [
      { source: "/rechner", destination: "/rechner/index.html" },
      ...RECHNER.map((slug) => ({
        source: `/rechner/${slug}`,
        destination: `/rechner/${slug}/index.html`,
      })),
    ];
  },

  async redirects() {
    return [
      /* Abschließender Schrägstrich soll nicht zu zwei indexierbaren Adressen führen. */
      { source: "/rechner/:slug/", destination: "/rechner/:slug", permanent: true },
    ];
  },

  async headers() {
    return [
      {
        source: "/rechner/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=0, s-maxage=3600, stale-while-revalidate=86400",
          },
          { key: "X-Content-Type-Options", value: "nosniff" },
        ],
      },
    ];
  },
};

module.exports.RECHNER = RECHNER;

